	const inflight = new Map(); // key -> Set<promise>
	const counters = { hits: 0, misses: 0, fetches: 0 };

	function isTwoOk(status) {
		return status >= 200 && status < 300;
	}

	async function doFetch(key) {
		counters.fetches++;
		const response = await fetchImpl(key);
		if (ttlMs > 0 && isTwoOk(response.status)) {
			cache.set(key, { status: response.status, body: clone(response.body), stamp: now() });
		}
		return response;
	}

	function track(key, promise) {
		let set = inflight.get(key);
		if (!set) {
			set = new Set();
			inflight.set(key, set);
		}
		set.add(promise);
		const drop = () => {
			set.delete(promise);
			if (set.size === 0) inflight.delete(key);
		};
		promise.then(drop, drop);
	}

	function respond(response) {
		return { status: response.status, body: clone(response.body) };
	}

